 RETURN account_plan;
END $function$
"}, {"id": "public.atomic_snapshot_valid(text, integer, jsonb, jsonb)", "acl": [{"grantee": "postgres", "grantable": false, "privilege": "EXECUTE"}, {"grantee": "service_role", "grantable": false, "privilege": "EXECUTE"}], "owner": "postgres", "definition": "CREATE OR REPLACE FUNCTION public.atomic_snapshot_valid(slug text, version integer, inputs jsonb, outputs jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
 SELECT coalesce(char_length(slug) BETWEEN 1 AND 160 AND btrim(slug)<>''
